/**
 * Attribute bundle bytes to source modules by decoding a Vite/Rollup source map.
 * Zero-dependency stand-in for source-map-explorer.
 *
 * Usage: node bench/bundle-report.mjs <bundle.js> [top=25]
 *   (needs <bundle.js>.map next to it; build with `vite build --sourcemap`)
 * Prints: total bytes, then the top N source files by generated bytes, plus a
 * per-package roll-up for node_modules.
 */
import { readFileSync } from 'node:fs';

const [, , bundlePath, topArg] = process.argv;
if (!bundlePath) {
  console.error('usage: node bench/bundle-report.mjs <bundle.js> [top]');
  process.exit(2);
}
const top = Number(topArg ?? 25);
const code = readFileSync(bundlePath, 'utf8');
const map = JSON.parse(readFileSync(`${bundlePath}.map`, 'utf8'));

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function decodeVlq(segment) {
  const out = [];
  let value = 0;
  let shift = 0;
  for (const ch of segment) {
    const digit = B64.indexOf(ch);
    const cont = digit & 32;
    value += (digit & 31) << shift;
    if (cont) {
      shift += 5;
    } else {
      const neg = value & 1;
      value >>= 1;
      out.push(neg ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

const lines = code.split('\n');
const bytesPerSource = new Map();
let unmapped = 0;
let srcIdx = 0;
const groups = map.mappings.split(';');
for (let li = 0; li < groups.length; li++) {
  const lineLen = Buffer.byteLength(lines[li] ?? '', 'utf8') + 1;
  const segs = groups[li] === '' ? [] : groups[li].split(',');
  let col = 0;
  const points = [];
  for (const seg of segs) {
    const f = decodeVlq(seg);
    col += f[0];
    if (f.length >= 4) srcIdx += f[1];
    points.push({ col, src: f.length >= 4 ? srcIdx : null });
  }
  if (points.length === 0) {
    unmapped += lineLen;
    continue;
  }
  if (points[0].col > 0) unmapped += points[0].col;
  for (let i = 0; i < points.length; i++) {
    const end = i + 1 < points.length ? points[i + 1].col : lineLen;
    const n = Math.max(0, end - points[i].col);
    const src = points[i].src;
    if (src === null) unmapped += n;
    else bytesPerSource.set(src, (bytesPerSource.get(src) ?? 0) + n);
  }
}

const total = Buffer.byteLength(code, 'utf8');
const rows = [...bytesPerSource.entries()]
  .map(([i, b]) => ({ file: map.sources[i], bytes: b }))
  .sort((a, b) => b.bytes - a.bytes);

function pkgOf(file) {
  const m = file.match(/node_modules\/((?:@[^/]+\/)?[^/]+)/);
  return m ? m[1] : '(app) ' + file.replace(/^(\.\.\/)+/, '');
}
const perPkg = new Map();
for (const r of rows) perPkg.set(pkgOf(r.file), (perPkg.get(pkgOf(r.file)) ?? 0) + r.bytes);
const pkgRows = [...perPkg.entries()].sort((a, b) => b[1] - a[1]);

const kb = (n) => (n / 1024).toFixed(1).padStart(7) + ' KB';
console.log(`bundle: ${bundlePath}`);
console.log(`total : ${kb(total)}  (unmapped/glue ${kb(unmapped)})`);
console.log('\n== top packages / app roots ==');
for (const [p, b] of pkgRows.slice(0, top))
  console.log(`${kb(b)}  ${((b / total) * 100).toFixed(1).padStart(5)}%  ${p}`);
console.log(`\n== top ${top} source files ==`);
for (const r of rows.slice(0, top))
  console.log(`${kb(r.bytes)}  ${((r.bytes / total) * 100).toFixed(1).padStart(5)}%  ${r.file}`);
